-- Resolve columns to flattened row slots, and validate before any execution.
import Json (..)
import Model (..)
import Data.List (..)
import Data.Foldable (all, any, length)

fn check(e : Expr, columns : List(Column), allow : Bool, inside : Bool) : Expr =
  if e.op == "col" then
    let matches = filter(
        \(c) -> c.name == e.name && (e.qualifier == "" || e.qualifier == c.qualifier),
        columns,
      )
    demand(length(matches) > 0, "UNKNOWN_COLUMN")
    demand(length(matches) == 1, "AMBIGUOUS_COLUMN")
    let c = at(matches, 0)
    Expr { ..e, index = c.index, source = c.source, kind = c.kind }
  elif e.op == "lit" then
    e
  else
    let isagg = agg(e.op)
    demand(not(isagg) || allow && not(inside), "INVALID_AGGREGATION")
    let args = map(\(a) -> check(a, columns, allow, inside || isagg), e.args)
    let ts = map(\(a) -> a.kind, args)
    let base = filter(\(t) -> t /= "null", ts)
    let kind =
      if e.op == "COUNT" then
        "int"
      elif elem(e.op, ["SUM", "+", "-", "*"]) then
        demand(all(\(t) -> t == "null" || t == "int", ts), "TYPE_ERROR")
        "int"
      elif elem(e.op, ["MIN", "MAX"]) then
        demand(length(base) == 0 || elem(at(base, 0), ["int", "text"]), "TYPE_ERROR")
        if length(base) == 0 then "null" else at(base, 0)
      elif e.op == "COALESCE" then
        demand(length(base) == 0 || all(\(t) -> t == at(base, 0), base), "TYPE_ERROR")
        if length(base) == 0 then "null" else at(base, 0)
      elif elem(e.op, ["ISNULL", "ISNOTNULL"]) then
        "bool"
      elif elem(e.op, ["NOT", "AND", "OR"]) then
        demand(all(\(t) -> t == "null" || t == "bool", ts), "TYPE_ERROR")
        "bool"
      else
        demand(
            length(base) <= 2 && (length(base) < 2 || at(base, 0) == at(base, 1))
              && (at(ts, 0) /= "bool" || elem(e.op, ["=", "<>"])),
            "TYPE_ERROR",
          )
        "bool"
    Expr { ..e, args = args, kind = kind }

fn predicate(e : Expr, columns : List(Column), allow : Bool) : Expr =
  let b = check(e, columns, allow, false)
  demand(b.kind == "bool", "TYPE_ERROR")
  b

pub fn tree_any(p : (Expr) -> Bool, e : Expr) : Bool =
  p(e) || any(\(a) -> tree_any(p, a), e.args)

fn grouped(e : Expr, keys : List(Int)) : Unit =
  if not(agg(e.op)) then
    demand(e.op /= "col" || elem(e.index, keys), "INVALID_AGGREGATION")
    for a in sof(e.args) do
      grouped(a, keys)

fn find_table(database : List(Table), name : String) : Table =
  let ts = filter(\(t) -> t.name == name, database)
  demand(length(ts) > 0, "UNKNOWN_TABLE")
  at(ts, 0)

pub fn bind(q : Query, database : List(Table)) : Plan =
  let aliases = map(snd, q.select)
  demand(unique(aliases), "DUPLICATE_ALIAS")
  demand(unique(map(snd, q.sources)), "DUPLICATE_ALIAS")
  let tables = map(\(s) -> find_table(database, fst(s)), q.sources)
  var columns := []
  var joins := []
  for i in srange(0, length(tables)) do
    let t = at(tables, i)
    let offset = length(columns)
    let qualifier = snd(at(q.sources, i))
    let cs = map(
        \(k) -> Column { ..at(t.columns, k), index = offset + k, source = i, qualifier = qualifier },
        range(0, length(t.columns)),
      )
    columns := append(columns, cs)
    if i > 0 then
      joins := append(joins, [predicate(at(q.joins, i - 1), columns, false)])
  let cs = columns
  let sels = map(\(s) -> (check(fst(s), cs, true, false), snd(s)), q.select)
  let groups = map(\(e) -> check(e, cs, false, false), q.groups)
  let keys = map(\(e) -> e.index, groups)
  demand(unique(map(show_int, keys)), "INVALID_AGGREGATION")
  let pred = predicate(q.predicate, cs, false)
  let hav = predicate(q.having, cs, true)
  let roots = append(map(fst, sels), [hav])
  let aggregate =
    length(groups) > 0 || any(\(e) -> tree_any(\(n) -> agg(n.op), e), roots)
  demand(not(q.has_having) || aggregate, "INVALID_AGGREGATION")
  if aggregate then
    for e in sof(roots) do
      grouped(e, keys)
  let order = map(\(o) -> (alias_index(aliases, fst(o), 0), snd(o)), q.order)
  let bq =
    Query {
      ..q,
      select = sels,
      joins = joins,
      groups = groups,
      predicate = pred,
      having = hav
    }
  Plan {
    query = bq,
    tables = tables,
    filters = map(\(_) -> [], tables),
    aggregate = aggregate,
    order = order
  }

fn alias_index(names : List(String), n : String, i : Int) : Int =
  match names of
    Nil =>
      reject("UNKNOWN_COLUMN")
      -1
    Cons(a, rest) =>
      if a == n then
        i
      else
        alias_index(rest, n, i + 1)

-- The parser owns a scoped token-state effect; all ASTs are immutable values.
import Json (..)
import Data.String (..)
import Data.List (..)
import Data.Foldable (all, length)
import Model (..)
import Control.State (..)

pub type Token = Token { word: String, value: Json }

fn tok(s : String) : Token = Token { word = s, value = JNull }

fn scan_string(s : String, i : Int, acc : String) : (String, Int) =
  demand(i < byte_len(s), "PARSE_ERROR")
  if byte_at(s, i) == 39 then
    if i + 1 < byte_len(s) && byte_at(s, i + 1) == 39 then
      scan_string(s, i + 2, concat(acc, "'"))
    else
      (acc, i + 1)
  else
    scan_string(s, i + 1, concat(acc, str_of_char(chr(byte_at(s, i)))))

fn scan_word(s : String, i : Int, numbers : Bool) : Int =
  if i >= byte_len(s) then
    i
  else
    let c = byte_at(s, i)
    if (digit(c) || not(numbers) && (letter(c) || c >= 65 && c <= 90)) then
      scan_word(s, i + 1, numbers)
    else
      i

fn slice(s : String, i : Int, j : Int) : String =
  string_of_buf(slice_bytes(s, i, j, buf_empty()))

fn lex(s : String, i : Int) : List(Token) =
  if i >= byte_len(s) then
    [tok("$END")]
  else
    let c = byte_at(s, i)
    if elem(c, [32, 9, 10, 13]) then
      lex(s, i + 1)
    elif c == 39 then
      let (v, j) = scan_string(s, i + 1, "")
      Cons(Token { word = "LITERAL", value = JStr(v) }, lex(s, j))
    elif digit(c) then
      let j = scan_word(s, i, true)
      let n =
        match parse_int(slice(s, i, j)) of
          Some(v) => v
          None => 0
      Cons(Token { word = "NUMBER", value = JInt(n) }, lex(s, j))
    elif letter(c) || c >= 65 && c <= 90 then
      let j = scan_word(s, i, false)
      let w = slice(s, i, j)
      Cons(tok(if reserved(w) then to_upper(w) else w), lex(s, j))
    else
      let two = slice(s, i, min(i + 2, byte_len(s)))
      if elem(two, ["<>", "<=", ">="]) then
        Cons(tok(two), lex(s, i + 2))
      else
        demand(
            elem(c, [40, 41, 44, 46, 59, 43, 45, 42, 61, 60, 62]),
            "PARSE_ERROR",
          )
        Cons(tok(str_of_char(chr(c))), lex(s, i + 1))

fn peek() : String ! {State(List(Token))} = at(get(), 0).word

fn pop() : Token ! {State(List(Token)), Domain} =
  let ts = get()
  let t = at(ts, 0)
  demand(t.word /= "$END", "PARSE_ERROR")
  put(tail(ts))
  t

fn accept(w : String) : Bool ! {State(List(Token))} =
  if peek() == w then
    let ts = get()
    put(tail(ts))
    true
  else
    false

fn expect(w : String) : Unit = demand(accept(w), "PARSE_ERROR")

fn name() : String =
  let w = pop().word
  demand(name_ok(w), "PARSE_ERROR")
  w

fn natural() : Int =
  let t = pop()
  demand(t.word == "NUMBER", "PARSE_ERROR")
  integer(t.value)

fn reference() : Expr =
  let n = name()
  if accept(".") then
    column_ref(n, name())
  else
    column_ref("", n)

fn source() : (String, String) =
  let n = name()
  (n, if accept("AS") then name() else n)

fn precedence(op : String) : Int =
  if op == "OR" then
    1
  elif op == "AND" then
    2
  elif elem(op, ["=", "<>", "<", ">", "<=", ">="]) then
    4
  elif elem(op, ["+", "-"]) then
    5
  elif op == "*" then
    6
  else
    0

fn expression(minimum : Int) : Expr =
  let t = pop()
  let w = t.word
  let e =
    if w == "NOT" then
      node(w, [expression(3)])
    elif w == "(" then
      let x = expression(1)
      expect(")")
      x
    elif w == "-" then
      literal(JInt(-natural()))
    elif elem(w, ["NUMBER", "LITERAL"]) then
      literal(t.value)
    elif elem(w, ["TRUE", "FALSE"]) then
      literal(JBool(w == "TRUE"))
    elif w == "NULL" then
      literal(JNull)
    elif w == "COALESCE" then
      expect("(")
      let first = expression(1)
      let xs = Cons(first, coalesce_tail())
      demand(length(xs) >= 2, "PARSE_ERROR")
      expect(")")
      node(w, xs)
    elif agg(w) then
      expect("(")
      let args =
        if w == "COUNT" && accept("*") then
          []
        else
          [expression(1)]
      expect(")")
      node(w, args)
    else
      demand(name_ok(w), "PARSE_ERROR")
      if accept(".") then
        column_ref(w, name())
      else
        column_ref("", w)
  binary(e, minimum, false)

fn coalesce_tail() : List(Expr) =
  if accept(",") then
    Cons(expression(1), coalesce_tail())
  else
    []

fn binary(left : Expr, minimum : Int, compared : Bool) : Expr =
  let op = peek()
  if op == "IS" then
    demand(minimum <= 4, "PARSE_ERROR")
    demand(not(compared), "PARSE_ERROR")
    let ignored = pop()
    let neg = accept("NOT")
    expect("NULL")
    binary(node(if neg then "ISNOTNULL" else "ISNULL", [left]), minimum, true)
  else
    let p = precedence(op)
    if p < minimum then
      left
    else
      demand(not(p == 4 && compared), "PARSE_ERROR")
      let ignored = pop()
      let right = expression(p + 1)
      binary(node(op, [left, right]), minimum, compared || p == 4)

fn selections() : List((Expr, String)) =
  let e = expression(1)
  expect("AS")
  let a = name()
  Cons((e, a), if accept(",") then selections() else [])

fn group_keys() : List(Expr) =
  let e = reference()
  Cons(e, if accept(",") then group_keys() else [])

fn order_keys() : List((String, Int)) =
  let n = name()
  let desc = accept("DESC")
  if not(desc) then
    let ignored = accept("ASC")
    ()
  let nulls =
    if accept("NULLS") then
      if accept("FIRST") then 0 else
        expect("LAST")
        1
    else
      if desc then 0 else 1
  Cons((n, (if desc then 2 else 0) + nulls), if accept(",") then order_keys() else [])

fn join_sources(
  ss : List((String, String)),
  js : List(Expr),
  ls : List(Bool)
) : (List((String, String)), List(Expr), List(Bool)) =
  if peek() == "LEFT" then
    let ignored = pop()
    let ignored2 = accept("OUTER")
    expect("JOIN")
    let s = source()
    expect("ON")
    let e = expression(1)
    join_sources(append(ss, [s]), append(js, [e]), append(ls, [true]))
  elif elem(peek(), ["INNER", "JOIN"]) then
    let ignored = accept("INNER")
    expect("JOIN")
    let s = source()
    expect("ON")
    let e = expression(1)
    join_sources(append(ss, [s]), append(js, [e]), append(ls, [false]))
  else
    (ss, js, ls)

fn query() : Query =
  expect("SELECT")
  let distinct = accept("DISTINCT")
  let sels = selections()
  expect("FROM")
  let (ss, js, ls) = join_sources([source()], [], [])
  let pred =
    if accept("WHERE") then
      expression(1)
    else
      literal(JBool(true))
  let groups =
    if accept("GROUP") then
      expect("BY")
      group_keys()
    else
      []
  let hh = accept("HAVING")
  let hav =
    if hh then
      expression(1)
    else
      literal(JBool(true))
  let order =
    if accept("ORDER") then
      expect("BY")
      order_keys()
    else
      []
  let lim =
    if accept("LIMIT") then
      natural()
    else
      -1
  let off =
    if lim >= 0 && accept("OFFSET") then
      natural()
    else
      0
  let ignored = accept(";")
  demand(peek() == "$END", "PARSE_ERROR")
  Query {
    select = sels,
    sources = ss,
    joins = js,
    left_joins = ls,
    predicate = pred,
    groups = groups,
    having = hav,
    has_having = hh,
    order = order,
    distinct = distinct,
    limit = lim,
    offset = off
  }

pub fn parse_sql(s : String) : Query = eval_state(lex(s, 0), query)

-- One request, one response. Domain effects abort the complete query batch.
import Json (..)
import Model (..)
import Parser (..)
import Binder (..)
import Engine (..)
import Data.List (..)
import Data.Foldable (all, any, length)

type Live = Live { table: Table, ids: List(Int), used: List(Int) }
type View = View { name: String, plan: Plan, result: Json, sources: List(String) }

fn validate_query(q : Json) : Unit =
  fields(q, ["sql", "optimize"])
  let ignored = text(getfield(q, "sql"))
  match getfield(q, "optimize") of
    JBool(_) => ()
    _ => reject("INVALID_INPUT")

fn query_mode(input : Json) : Json =
  fields(input, ["database", "queries"])
  let db = map(validate_table, arr(getfield(input, "database")))
  demand(unique(map(\(t) -> t.name, db)), "INVALID_INPUT")
  let qs = arr(getfield(input, "queries"))
  for q in sof(qs) do validate_query(q)
  let rs = map(\(q) -> let p = bind(parse_sql(text(getfield(q, "sql"))), db) in execute(if truth(getfield(q, "optimize")) then optimize(p) else p), qs)
  JObj([("ok", JBool(true)), ("result", JObj([("results", JArr(rs))]))])

fn make_live(t : Table) : Live =
  let ids = map(\(i) -> i + 1, range(0, length(t.rows)))
  Live { table = t, ids = ids, used = ids }

fn get_live(ts : List(Live), n : String) : Live =
  match ts of
    Nil =>
      reject("UNKNOWN_TABLE")
      Live { table = Table { name = "", columns = [], rows = [] }, ids = [], used = [] }
    Cons(x, rest) => if x.table.name == n then x else get_live(rest, n)

fn put_live(ts : List(Live), x : Live) : List(Live) = map(\(y) -> if y.table.name == x.table.name then x else y, ts)

fn ids_has(xs : List(Int), n : Int) : Bool = elem(n, xs)

fn row_replace(rs : List(List(Json)), ids : List(Int), id : Int, row : List(Json)) : List(List(Json)) =
  match (rs, ids) of
    (Cons(old, rest), Cons(i, more)) => Cons(if i == id then row else old, row_replace(rest, more, id, row))
    _ => []

fn row_delete(rs : List(List(Json)), ids : List(Int), id : Int) : List(List(Json)) =
  match (rs, ids) of
    (Cons(old, rest), Cons(i, more)) => if i == id then row_delete(rest, more, id) else Cons(old, row_delete(rest, more, id))
    _ => []

fn valid_row(t : Table, row : List(Json)) : Unit =
  demand(length(row) == length(t.columns), "INVALID_ROW")
  for i in srange(0, length(row)) do
    let v = value_type(at(row, i))
    let c = at(t.columns, i)
    demand(v == c.kind || v == "null" && c.nullable, "INVALID_ROW")

fn change(c : Json, ts : List(Live)) : (List(Live), String) =
  let op = text(getfield(c, "op"))
  let n = text(getfield(c, "table"))
  let x = get_live(ts, n)
  let id = integer(getfield(c, "id"))
  if op == "insert" then
    demand(not(ids_has(x.used, id)), "ROW_ID_USED")
    let row = arr(getfield(c, "row"))
    valid_row(x.table, row)
    let nt = Table { ..x.table, rows = append(x.table.rows, [row]) }
    (put_live(ts, Live { ..x, table = nt, ids = append(x.ids, [id]), used = append(x.used, [id]) }), n)
  elif op == "update" then
    demand(ids_has(x.ids, id), "UNKNOWN_ROW")
    let row = arr(getfield(c, "row"))
    valid_row(x.table, row)
    let nt = Table { ..x.table, rows = row_replace(x.table.rows, x.ids, id, row) }
    (put_live(ts, Live { ..x, table = nt }), n)
  else
    demand(ids_has(x.ids, id), "UNKNOWN_ROW")
    let nt = Table { ..x.table, rows = row_delete(x.table.rows, x.ids, id) }
    (put_live(ts, Live { ..x, table = nt, ids = filter(\(i) -> i /= id, x.ids) }), n)

fn refresh_view(v : View, ts : List(Live), names : List(String)) : View =
  if any(\(n) -> elem(n, names), v.sources) then
    let p = Plan { ..v.plan, tables = map(\(t) -> get_live(ts, t.name).table, v.plan.tables) } in
    View { ..v, plan = p, result = execute(p) }
  else v

fn command_shape(c : Json) : Unit =
  let op = text(getfield(c, "op"))
  if op == "insert" || op == "update" then
    fields(c, ["op", "table", "id", "row"])
    demand(value_type(getfield(c, "id")) == "int" && integer(getfield(c, "id")) > 0 && integer(getfield(c, "id")) <= 2147483647, "INVALID_COMMAND")
    let ignored = text(getfield(c, "table")) in
    let ignored2 = arr(getfield(c, "row")) in ()
  elif op == "delete" then
    fields(c, ["op", "table", "id"])
    demand(value_type(getfield(c, "id")) == "int" && integer(getfield(c, "id")) > 0 && integer(getfield(c, "id")) <= 2147483647, "INVALID_COMMAND")
    let ignored = text(getfield(c, "table")) in ()
  else
    reject("INVALID_COMMAND")
    ()

fn update_views(vs : List(View), ts : List(Live), names : List(String)) : List(View) = map(\(v) -> refresh_view(v, ts, names), vs)

fn command(c : Json, db : List(Table), ts : List(Live), vs : List(View), rev : Int) : (List(Live), List(View), Json, Bool) =
  let op = text(getfield(c, "op"))
  if op == "create" then
    fields(c, ["op", "view", "sql", "optimize"])
    let n = text(getfield(c, "view"))
    demand(view_ok(n), "INVALID_COMMAND")
    demand(not(any(\(v) -> v.name == n, vs)), "VIEW_EXISTS")
    let p0 = bind(parse_sql(text(getfield(c, "sql"))), db)
    let p = if truth(getfield(c, "optimize")) then optimize(p0) else p0
    let p2 = Plan { ..p, tables = map(\(t) -> get_live(ts, t.name).table, p.tables) }
    let v = View { name = n, plan = p2, result = execute(p2), sources = map(fst, p2.query.sources) }
    (ts, append(vs, [v]), JObj([("view", JStr(n)), ("revision", JInt(rev))]), false)
  elif op == "read" then
    fields(c, ["op", "view"])
    let n = text(getfield(c, "view"))
    let v = find_view(vs, n)
    (ts, vs, add_rev(v.result, rev), false)
  elif op == "drop" then
    fields(c, ["op", "view"])
    let n = text(getfield(c, "view"))
    let ignored = find_view(vs, n)
    (ts, filter(\(v) -> v.name /= n, vs), JObj([("dropped", JStr(n))]), false)
  elif op == "apply" then
    fields(c, ["op", "changes"])
    let xs = arr(getfield(c, "changes"))
    demand(length(xs) > 0 && length(xs) <= 200, "INVALID_COMMAND")
    for x in sof(xs) do command_shape(x)
    let (nts, names) = apply_all(xs, ts, [])
    (nts, update_views(vs, nts, names), JObj([("revision", JInt(rev + 1))]), true)
  else
    reject("INVALID_COMMAND")
    (ts, vs, JNull, false)

fn apply_all(xs : List(Json), ts : List(Live), names : List(String)) : (List(Live), List(String)) =
  match xs of
    Nil => (ts, names)
    Cons(c, rest) => let (nt, n) = change(c, ts) in apply_all(rest, nt, append(names, [n]))

fn view_ok(s : String) : Bool = byte_len(s) > 0 && byte_len(s) <= 40 && letter(byte_at(s, 0)) && all(\(i) -> letter(byte_at(s, i)) || digit(byte_at(s, i)) || byte_at(s, i) == 45, range(0, byte_len(s)))

fn find_view(vs : List(View), n : String) : View =
  match vs of
    Nil =>
      reject("UNKNOWN_VIEW")
      View { name = "", plan = Plan { query = Query { select = [], sources = [], joins = [], left_joins = [], predicate = literal(JBool(true)), groups = [], having = literal(JBool(true)), has_having = false, order = [], distinct = false, limit = -1, offset = 0 }, tables = [], filters = [], aggregate = false, order = [] }, result = JNull, sources = [] }
    Cons(v, rest) => if v.name == n then v else find_view(rest, n)

fn add_rev(j : Json, n : Int) : Json =
  match j of
    JObj(fs) => JObj(append(fs, [("revision", JInt(n))]))
    _ => j

fn command_mode(input : Json) : Json =
  fields(input, ["database", "commands"])
  let db = map(validate_table, arr(getfield(input, "database")))
  demand(unique(map(\(t) -> t.name, db)), "INVALID_INPUT")
  var ts := map(make_live, db)
  var vs : List(View) := []
  var rev := 0
  var out := []
  let commands = arr(getfield(input, "commands"))
  demand(length(commands) <= 200, "INVALID_COMMAND")
  for c in sof(commands) do
    let (nt, nv, reply, advances) = handle command(c, db, ts, vs, rev) with
      never reject(code) => (ts, vs, error_response(code), false)
      return x => x
    ts := nt
    vs := nv
    rev := if advances then rev + 1 else rev
    out := append(out, [if op_failed(reply) then reply else JObj([("ok", JBool(true)), ("result", reply)])])
  JObj([("ok", JBool(true)), ("result", JObj([("results", JArr(out))]))])

fn op_failed(j : Json) : Bool = hasfield(j, "ok") && not(truth(getfield(j, "ok")))

fn work(request : Json) : Json =
  demand(
      value_type(getfield(request, "protocol_version")) == "int"
        && integer(getfield(request, "protocol_version")) == 1,
      "INVALID_INPUT",
    )
  demand(text(getfield(request, "task")) == "query-null", "INVALID_INPUT")
  let input = getfield(request, "input")
  demand(hasfield(input, "queries") /= hasfield(input, "commands"), "INVALID_INPUT")
  if hasfield(input, "queries") then query_mode(input) else command_mode(input)

fn error_response(code : String) : Json =
  JObj([("ok", JBool(false)), ("error", JObj([("code", JStr(code))]))])

fn decode_work(line : String) : Json =
  match decode_lossy(line) of
    Ok(request) => work(request)
    Err(_) => error_response("INVALID_INPUT")

fn main() =
