fn check(e : Expr, columns : List(Column), allow : Bool, inside : Bool) : Expr =
  if e.op == "col" then
    let matches = filter(
        \(c) -> c.name == e.name && (e.qualifier == "" || e.qualifier == c.qualifier),
        columns,
      )
    demand(length(matches) > 0, "UNKNOWN_COLUMN")
    demand(length(matches) == 1, "AMBIGUOUS_COLUMN")
    let c = at(matches, 0)
    Expr { ..e, index = c.index, source = c.source, kind = c.kind }
  elif e.op == "lit" then
    e
  else
    let isagg = agg(e.op)
    demand(not(isagg) || allow && not(inside), "INVALID_AGGREGATION")
    let args = map(\(a) -> check(a, columns, allow, inside || isagg), e.args)
    let ts = map(\(a) -> a.kind, args)
    let base = filter(\(t) -> t /= "null", ts)
    let kind =
      if e.op == "COUNT" then
        "int"
      elif elem(e.op, ["SUM", "+", "-", "*"]) then
        demand(all(\(t) -> t == "null" || t == "int", ts), "TYPE_ERROR")
        "int"
      elif elem(e.op, ["MIN", "MAX"]) then
        demand(length(base) == 0 || elem(at(base, 0), ["int", "text"]), "TYPE_ERROR")
        if length(base) == 0 then "null" else at(base, 0)
      elif e.op == "COALESCE" then
        demand(length(base) == 0 || all(\(t) -> t == at(base, 0), base), "TYPE_ERROR")
        if length(base) == 0 then "null" else at(base, 0)
      elif elem(e.op, ["ISNULL", "ISNOTNULL"]) then
        "bool"
      elif elem(e.op, ["NOT", "AND", "OR"]) then
        demand(all(\(t) -> t == "null" || t == "bool", ts), "TYPE_ERROR")
        "bool"
      else
        demand(
            length(base) <= 2 && (length(base) < 2 || at(base, 0) == at(base, 1))
              && (at(ts, 0) /= "bool" || elem(e.op, ["=", "<>"])),
            "TYPE_ERROR",
          )
        "bool"
    Expr { ..e, args = args, kind = kind }

fn predicate(e : Expr, columns : List(Column), allow : Bool) : Expr =
  let b = check(e, columns, allow, false)
  demand(b.kind == "bool", "TYPE_ERROR")
  b

fn find_table(database : List(Table), name : String) : Table =
  let ts = filter(\(t) -> t.name == name, database)
  demand(length(ts) > 0, "UNKNOWN_TABLE")
  at(ts, 0)

fn bind(q : Query, database : List(Table)) : Plan =
  let aliases = map(snd, q.select)
  demand(unique(aliases), "DUPLICATE_ALIAS")
  demand(unique(map(snd, q.sources)), "DUPLICATE_ALIAS")
  let tables = map(\(s) -> find_table(database, fst(s)), q.sources)
  var columns := []
  var joins := []
  for i in srange(0, length(tables)) do
    let t = at(tables, i)
    let offset = length(columns)
    let qualifier = snd(at(q.sources, i))
    let cs = map(
        \(k) -> Column { ..at(t.columns, k), index = offset + k, source = i, qualifier = qualifier },
        range(0, length(t.columns)),
      )
    columns := append(columns, cs)
    if i > 0 then
      joins := append(joins, [predicate(at(q.joins, i - 1), columns, false)])
  let cs = columns
  let sels = map(\(s) -> (check(fst(s), cs, true, false), snd(s)), q.select)
  let groups = map(\(e) -> check(e, cs, false, false), q.groups)
  let keys = map(\(e) -> e.index, groups)
  demand(unique(map(show_int, keys)), "INVALID_AGGREGATION")
  let pred = predicate(q.predicate, cs, false)
  let hav = predicate(q.having, cs, true)
  let roots = append(map(fst, sels), [hav])
  let aggregate =
    length(groups) > 0 || any(\(e) -> tree_any(\(n) -> agg(n.op), e), roots)
  demand(not(q.has_having) || aggregate, "INVALID_AGGREGATION")
  if aggregate then
    for e in sof(roots) do
      grouped(e, keys)
  let order = map(\(o) -> (alias_index(aliases, fst(o), 0), snd(o)), q.order)
  let bq =
    Query {
      ..q,
      select = sels,
      joins = joins,
      groups = groups,
      predicate = pred,
      having = hav
    }
  Plan {
    query = bq,
    tables = tables,
    filters = map(\(_) -> [], tables),
    aggregate = aggregate,
    order = order
  }

fn cmp3(a : Json, b : Json, op : String) : Json =
  if isnull(a) || isnull(b) then JNull else
    let c = compare_value(a, b)
    JBool(if op == "=" then c == 0 elif op == "<>" then c /= 0 elif op == "<" then c < 0 elif op == ">" then c > 0 elif op == "<=" then c <= 0 else c >= 0)

fn evaluate(e : Expr, row : List(Json), group : List(List(Json))) : Json =
  let op = e.op
  if op == "lit" then
    e.value
  elif op == "col" then
    at(row, e.index)
  elif agg(op) then
    if op == "COUNT" then
      if length(e.args) == 0 then JInt(length(group))
      else JInt(length(filter(\(r) -> not(isnull(evaluate(at(e.args, 0), r, []))), group)))
    else
      let vs = map(\(r) -> evaluate(at(e.args, 0), r, []), group)
      if op == "SUM" then
        let ns = filter(\(v) -> not(isnull(v)), vs)
        if length(ns) == 0 then JNull else JInt(sum(map(integer, ns)))
      else
        extremum(vs, op == "MIN")
  else
    let a = evaluate(at(e.args, 0), row, group)
    if op == "NOT" then
      if isnull(a) then JNull else JBool(not(truth(a)))
    elif op == "ISNULL" then JBool(isnull(a))
    elif op == "ISNOTNULL" then JBool(not(isnull(a)))
    elif op == "COALESCE" then coalesce(e.args, row, group)
    else
      let b = evaluate(at(e.args, 1), row, group)
      if op == "+" then
        if isnull(a) || isnull(b) then JNull else JInt(integer(a) + integer(b))
      elif op == "-" then
        if isnull(a) || isnull(b) then JNull else JInt(integer(a) - integer(b))
      elif op == "*" then
        if isnull(a) || isnull(b) then JNull else JInt(integer(a) * integer(b))
      elif op == "AND" then
        bool3(if truth3(a) == 0 || truth3(b) == 0 then 0 elif truth3(a) == 1 && truth3(b) == 1 then 1 else -1)
      elif op == "OR" then
        bool3(if truth3(a) == 1 || truth3(b) == 1 then 1 elif truth3(a) == 0 && truth3(b) == 0 then 0 else -1)
      else
        cmp3(a, b, op)

fn fold_constants(e : Expr) : Expr =
  let n = Expr { ..e, args = map(fold_constants, e.args) }
  if (not(agg(n.op))
      && not(elem(n.op, ["lit", "col"]))
      && all(\(a) -> a.op == "lit", n.args)) then
    literal(evaluate(n, [], []))
  else
    n

fn combine(es : List(Expr)) : Expr =
  match es of
    Nil => literal(JBool(true))
    Cons(e, Nil) => e
    Cons(e, rest) => Expr { ..node("AND", [e, combine(rest)]), kind = "bool" }

fn optimize(plan : Plan) : Plan =
  let q = plan.query
  let terms = conjuncts(fold_constants(q.predicate))
  let pushable = \(e) -> let ss = sources(e) in length(plan.tables) > 1 && length(ss) > 0 && all(\(s) -> s == at(ss, 0), ss)
  let safe = \(e) -> pushable(e) && (at(sources(e), 0) == 0 || not(at(q.left_joins, at(sources(e), 0) - 1)))
  let fs = map(
      \(i) -> filter(\(e) -> safe(e) && at(sources(e), 0) == i, terms),
      range(0, length(plan.tables)),
    )
  let rem = filter(\(e) -> not(safe(e)), terms)
  let bq = Query {
    ..q,
    predicate = combine(rem),
    select = map(\(s) -> (fold_constants(fst(s)), snd(s)), q.select),
    joins = map(fold_constants, q.joins),
    having = fold_constants(q.having)
  }
  Plan { ..plan, query = bq, filters = fs }

fn join_rows(
  left : List(List(Json)),
  right : List(List(Json)),
  on : Expr,
  left_join : Bool,
  right_width : Int
) : List(List(Json)) =
  flatten(map(\(l) ->
    let hits = filter(\(r) -> truth3(evaluate(on, append(l, r), [])) == 1, right)
    in if length(hits) > 0 then map(\(r) -> append(l, r), hits)
       elif left_join then [append(l, replicate(right_width, JNull))] else [], left))

fn row_compare(
  a : List(Json),
  b : List(Json),
  order : List((Int, Int))
) : Int =
  match order of
    Nil => 0
    Cons((i, code), rest) =>
      let desc = code >= 2
      let nulls = if code % 2 == 0 then 0 else 1
      let av = at(a, i)
      let bv = at(b, i)
      let either_null = isnull(av) || isnull(bv)
      let c = if isnull(av) && isnull(bv) then 0 elif isnull(av) then (if nulls == 0 then -1 else 1) elif isnull(bv) then (if nulls == 0 then 1 else -1) else compare_value(av, bv)
      if c == 0 then
        row_compare(a, b, rest)
      elif desc && not(either_null) then
        -c
      else
        c

fn execute(plan : Plan) : Json =
  let q = plan.query
  var scans := []
  var offset := 0
  for i in srange(0, length(plan.tables)) do
    let t = at(plan.tables, i)
    let padding = replicate(offset, JNull)
    let predicates = at(plan.filters, i)
    let rs = filter(
        \(r) -> all(\(p) -> truth(evaluate(p, append(padding, r), [])), predicates),
        t.rows,
      )
    scans := append(scans, [rs])
    offset += length(t.columns)
  var rows := at(scans, 0)
  for i in srange(0, length(q.joins)) do
    rows := join_rows(rows, at(scans, i + 1), at(q.joins, i), at(q.left_joins, i), length(at(plan.tables, i + 1).columns))
  let filtered = filter(\(r) -> truth(evaluate(q.predicate, r, [])), rows)
  let projected =
    if plan.aggregate then
      flatten(
          map(
              \(g) -> project(q, if length(g.rows) > 0 then at(g.rows, 0) else [], g.rows),
              groups_for(filtered, q.groups),
            ),
        )
    else
      flatten(map(\(r) -> project(q, r, []), filtered))
  let distinct =
    if q.distinct then
      distinct_rows(projected, [])
    else
      projected
  let sorted =
    if length(plan.order) > 0 then
      sort_rows(distinct, plan.order)
    else
      distinct
  let skipped = drop(q.offset, sorted)
  let final =
    if q.limit >= 0 then
      take(q.limit, skipped)
    else
      skipped
  JObj([
      ("columns", JArr(map(\(s) -> JStr(snd(s)), q.select))),
      ("rows", JArr(map(JArr, final))),
    ])

fn demand(b : Bool, code : String) : Unit =
  if not(b) then
    reject(code)

fn reserved(s : String) : Bool =
  elem(
      to_upper(s),
      split(
          32,
          "SELECT DISTINCT AS FROM INNER JOIN LEFT OUTER ON WHERE GROUP BY HAVING ORDER ASC DESC NULLS FIRST LAST LIMIT OFFSET AND OR NOT IS NULL TRUE FALSE COALESCE COUNT SUM MIN MAX",
        ),
    )

type Table = Table {
  name: String,
  columns: List(Column),
  rows: List(List(Json))
}

fn validate_table(j : Json) : Table =
  fields(j, ["name", "columns", "rows"])
  let n = text(getfield(j, "name"))
  demand(name_ok(n), "INVALID_INPUT")
  let cs = map(validate_column, arr(getfield(j, "columns")))
  demand(length(cs) > 0, "INVALID_INPUT")
  demand(unique(map(\(c) -> c.name, cs)), "INVALID_INPUT")
  let rows = map(arr, arr(getfield(j, "rows")))
  for row in sof(rows) do
    demand(length(row) == length(cs), "INVALID_INPUT")
    for i in srange(0, length(cs)) do
      let v = at(row, i)
      demand(value_type(v) == at(cs, i).kind || value_type(v) == "null" && at(cs, i).nullable, "INVALID_INPUT")
  Table { name = n, columns = cs, rows = rows }

fn pop() : Token ! {State(List(Token)), Domain} =
  let ts = get()
  let t = at(ts, 0)
  demand(t.word /= "$END", "PARSE_ERROR")
  put(tail(ts))
  t

fn natural() : Int =
  let t = pop()
  demand(t.word == "NUMBER", "PARSE_ERROR")
  integer(t.value)

fn reference() : Expr =
  let n = name()
  if accept(".") then
    column_ref(n, name())
  else
    column_ref("", n)

fn source() : (String, String) =
  let n = name()
  (n, if accept("AS") then name() else n)

fn binary(left : Expr, minimum : Int, compared : Bool) : Expr =
  let op = peek()
  if op == "IS" then
    demand(minimum <= 4, "PARSE_ERROR")
    demand(not(compared), "PARSE_ERROR")
    let ignored = pop()
    let neg = accept("NOT")
    expect("NULL")
    binary(node(if neg then "ISNOTNULL" else "ISNULL", [left]), minimum, true)
  else
    let p = precedence(op)
    if p < minimum then
      left
    else
      demand(not(p == 4 && compared), "PARSE_ERROR")
      let ignored = pop()
      let right = expression(p + 1)
      binary(node(op, [left, right]), minimum, compared || p == 4)

fn selections() : List((Expr, String)) =
  let e = expression(1)
  expect("AS")
  let a = name()
  Cons((e, a), if accept(",") then selections() else [])

fn group_keys() : List(Expr) =
  let e = reference()
  Cons(e, if accept(",") then group_keys() else [])

fn order_keys() : List((String, Int)) =
  let n = name()
  let desc = accept("DESC")
  if not(desc) then
    let ignored = accept("ASC")
    ()
  let nulls =
    if accept("NULLS") then
      if accept("FIRST") then 0 else
        expect("LAST")
        1
    else
      if desc then 0 else 1
  Cons((n, (if desc then 2 else 0) + nulls), if accept(",") then order_keys() else [])

fn join_sources(
  ss : List((String, String)),
  js : List(Expr),
  ls : List(Bool)
) : (List((String, String)), List(Expr), List(Bool)) =
  if peek() == "LEFT" then
    let ignored = pop()
    let ignored2 = accept("OUTER")
    expect("JOIN")
    let s = source()
    expect("ON")
    let e = expression(1)
    join_sources(append(ss, [s]), append(js, [e]), append(ls, [true]))
  elif elem(peek(), ["INNER", "JOIN"]) then
    let ignored = accept("INNER")
    expect("JOIN")
    let s = source()
    expect("ON")
    let e = expression(1)
    join_sources(append(ss, [s]), append(js, [e]), append(ls, [false]))
  else
    (ss, js, ls)

fn validate_query(q : Json) : Unit =
  fields(q, ["sql", "optimize"])
  let ignored = text(getfield(q, "sql"))
  match getfield(q, "optimize") of
    JBool(_) => ()
    _ => reject("INVALID_INPUT")

fn query_mode(input : Json) : Json =
  fields(input, ["database", "queries"])
  let db = map(validate_table, arr(getfield(input, "database")))
  demand(unique(map(\(t) -> t.name, db)), "INVALID_INPUT")
  let qs = arr(getfield(input, "queries"))
  for q in sof(qs) do validate_query(q)
  let rs = map(\(q) -> let p = bind(parse_sql(text(getfield(q, "sql"))), db) in execute(if truth(getfield(q, "optimize")) then optimize(p) else p), qs)
  JObj([("ok", JBool(true)), ("result", JObj([("results", JArr(rs))]))])

fn make_live(t : Table) : Live =
  let ids = map(\(i) -> i + 1, range(0, length(t.rows)))
  Live { table = t, ids = ids, used = ids }

fn get_live(ts : List(Live), n : String) : Live =
  match ts of
    Nil =>
      reject("UNKNOWN_TABLE")
      Live { table = Table { name = "", columns = [], rows = [] }, ids = [], used = [] }
    Cons(x, rest) => if x.table.name == n then x else get_live(rest, n)

fn valid_row(t : Table, row : List(Json)) : Unit =
  demand(length(row) == length(t.columns), "INVALID_ROW")
  for i in srange(0, length(row)) do
    let v = value_type(at(row, i))
    let c = at(t.columns, i)
    demand(v == c.kind || v == "null" && c.nullable, "INVALID_ROW")

fn change(c : Json, ts : List(Live)) : (List(Live), String) =
  let op = text(getfield(c, "op"))
  let n = text(getfield(c, "table"))
  let x = get_live(ts, n)
  let id = integer(getfield(c, "id"))
  if op == "insert" then
    demand(not(ids_has(x.used, id)), "ROW_ID_USED")
    let row = arr(getfield(c, "row"))
    valid_row(x.table, row)
    let nt = Table { ..x.table, rows = append(x.table.rows, [row]) }
    (put_live(ts, Live { ..x, table = nt, ids = append(x.ids, [id]), used = append(x.used, [id]) }), n)
  elif op == "update" then
    demand(ids_has(x.ids, id), "UNKNOWN_ROW")
    let row = arr(getfield(c, "row"))
    valid_row(x.table, row)
    let nt = Table { ..x.table, rows = row_replace(x.table.rows, x.ids, id, row) }
    (put_live(ts, Live { ..x, table = nt }), n)
  else
    demand(ids_has(x.ids, id), "UNKNOWN_ROW")
    let nt = Table { ..x.table, rows = row_delete(x.table.rows, x.ids, id) }
    (put_live(ts, Live { ..x, table = nt, ids = filter(\(i) -> i /= id, x.ids) }), n)

fn refresh_view(v : View, ts : List(Live), names : List(String)) : View =
  if any(\(n) -> elem(n, names), v.sources) then
    let p = Plan { ..v.plan, tables = map(\(t) -> get_live(ts, t.name).table, v.plan.tables) } in
    View { ..v, plan = p, result = execute(p) }
  else v

fn command(c : Json, db : List(Table), ts : List(Live), vs : List(View), rev : Int) : (List(Live), List(View), Json, Bool) =
  let op = text(getfield(c, "op"))
  if op == "create" then
    fields(c, ["op", "view", "sql", "optimize"])
    let n = text(getfield(c, "view"))
    demand(view_ok(n), "INVALID_COMMAND")
    demand(not(any(\(v) -> v.name == n, vs)), "VIEW_EXISTS")
    let p0 = bind(parse_sql(text(getfield(c, "sql"))), db)
    let p = if truth(getfield(c, "optimize")) then optimize(p0) else p0
    let p2 = Plan { ..p, tables = map(\(t) -> get_live(ts, t.name).table, p.tables) }
    let v = View { name = n, plan = p2, result = execute(p2), sources = map(fst, p2.query.sources) }
    (ts, append(vs, [v]), JObj([("view", JStr(n)), ("revision", JInt(rev))]), false)
  elif op == "read" then
    fields(c, ["op", "view"])
    let n = text(getfield(c, "view"))
    let v = find_view(vs, n)
    (ts, vs, add_rev(v.result, rev), false)
  elif op == "drop" then
    fields(c, ["op", "view"])
    let n = text(getfield(c, "view"))
    let ignored = find_view(vs, n)
    (ts, filter(\(v) -> v.name /= n, vs), JObj([("dropped", JStr(n))]), false)
  elif op == "apply" then
    fields(c, ["op", "changes"])
    let xs = arr(getfield(c, "changes"))
    demand(length(xs) > 0 && length(xs) <= 200, "INVALID_COMMAND")
    for x in sof(xs) do command_shape(x)
    let (nts, names) = apply_all(xs, ts, [])
    (nts, update_views(vs, nts, names), JObj([("revision", JInt(rev + 1))]), true)
  else
    reject("INVALID_COMMAND")
    (ts, vs, JNull, false)

fn find_view(vs : List(View), n : String) : View =
  match vs of
    Nil =>
      reject("UNKNOWN_VIEW")
      View { name = "", plan = Plan { query = Query { select = [], sources = [], joins = [], left_joins = [], predicate = literal(JBool(true)), groups = [], having = literal(JBool(true)), has_having = false, order = [], distinct = false, limit = -1, offset = 0 }, tables = [], filters = [], aggregate = false, order = [] }, result = JNull, sources = [] }
    Cons(v, rest) => if v.name == n then v else find_view(rest, n)

fn work(request : Json) : Json =
  demand(
      value_type(getfield(request, "protocol_version")) == "int"
        && integer(getfield(request, "protocol_version")) == 1,
      "INVALID_INPUT",
    )
  demand(text(getfield(request, "task")) == "query-null", "INVALID_INPUT")
  let input = getfield(request, "input")
  demand(hasfield(input, "queries") /= hasfield(input, "commands"), "INVALID_INPUT")
  if hasfield(input, "queries") then query_mode(input) else command_mode(input)

fn main() =
  let line = read_line()
  let response =
    handle decode_work(line) with
      never reject(code) => error_response(code)
      return result => result
  println(encode(response))
